      "path": "package.json",
      "content": "{\n  \"name\": \"meow-cachebilling\",\n  \"version\": \"0.8.0\",\n  \"description\": \"喵账单：上下文圆环弹层里实时算账——一步/一轮/会话三行各带总价，缓存命中/未命中/输出三列明细的无边框小账表，外加当前模型的平均累计花费曲线（帮你赶在花销起飞前换窗口），峰谷/一口价自动计价（价目表 rates.yml 可手填），专治『缓存命中率 100% 却越用越贵』\",\n  \"keywords\": [\n    \"deepseek-harness\",\n    \"dsh\",\n    \"dsh-plugin\",\n    \"billing\",\n    \"cache-hit\",\n    \"cost\",\n    \"peak-offpeak\"\n  ],\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/Phant0Meow/dsh-meow-cachebilling.git\"\n  },\n  \"author\": \"Phant0Meow\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib/index.js\",\n    \"lib/index.js.map\",\n    \"lib/client.js\",\n    \"lib/client.js.map\",\n    \"cordis.patch.yml\",\n    \"rates.yml\"\n  ],\n  \"license\": \"MIT\",\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"platform\": \"web\",\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-ui-settings-plugins\"\n      ]\n    }\n  },\n  \"scripts\": {\n    \"prepare\": \"node build.mjs\",\n    \"build\": \"node build.mjs\",\n    \"watch\": \"node build.mjs --watch\",\n    \"test\": \"node tests/settings-mount.mjs && node tests/config-volatile.mjs && node tests/rates-holidays-compat.mjs\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/dsh-settings\": \"^0.1.1-rc.2\",\n    \"@deepseek-ai/dsh-storage-domain\": \"^0.1.1-rc.2\",\n    \"@deepseek-ai/schemastery\": \"3.18.1\",\n    \"esbuild\": \"^0.25.0\",\n    \"yaml\": \"^2.9.0\",\n    \"zod\": \"^4.4.3\"\n  }\n}\n"
